SELECT p.gender, s.admission_type_id, ph.drug_class, ph.drug_name, ph.drug_strength, ph.drug_form, ph.drug_frequency, ph.drug_duration, ph.drug_rate, row_number() OVER(PARTITION BY p.gender, s.admission_type_id, ph.drug_class, ph.drug_name, ph.drug_strength, ph.drug_form, ph.drug_frequency, ph.drug_duration, ph.drug_rate ORDER BY a.length_of_stay DESC) AS rn, COUNT(*) OVER(PARTITION BY p.gender, s.admission_type_id, ph.drug_class, ph.drug_name, ph.drug_strength, ph.drug_form, ph.drug_frequency, ph.drug_duration, ph.drug_rate) AS drug_count, SUM(CASE WHEN a.death_date IS NOT NULL THEN 1 ELSE 0 END) OVER(PARTITION BY p.gender, s.admission_type_id, ph.drug_class, ph.drug_name, ph.drug_strength, ph.drug_form, ph.drug_frequency, ph.drug_duration, ph.drug_rate) AS death_count, SUM(CASE WHEN a.readmission_date IS NOT NULL AND a.readmission_date <= a.discharge_date + interval '30 days' THEN 1 ELSE 0 END) OVER(PARTITION BY p.gender, s.admission_type_id, ph.drug_class, ph.drug_name, ph.drug_strength, ph.drug_form, ph.drug_frequency, ph.drug_duration, ph.drug_rate) AS readmission_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN pharmacy_treatments ph ON a.subject_id = ph.patient_id WHERE p.gender = 'F' AND s.admission_type_id = 757071 AND p.anchor_age >= 51 AND p.anchor_age <= 61 AND ph.drug_class IS NOT NULL AND ph.drug_name IS NOT NULL AND ph.drug_strength IS NOT NULL AND ph.drug_form IS NOT NULL AND ph.drug_frequency IS NOT NULL AND ph.drug_duration IS NOT NULL AND ph.drug_rate IS NOT NULL AND rn <= 4;